import test from "node:test";
import assert from "node:assert/strict";
import { double, halve, doubleInternal, halveInternal } from "../lib/util.mjs";

test("helpers", () => {
  assert.equal(doubleInternal(4), 8);
  assert.equal(halveInternal(4), 2);
});

test("new names match old aliases", () => {
  assert.equal(double(4), 8);
  assert.equal(halve(4), 2);
  assert.equal(double, doubleInternal);
  assert.equal(halve, halveInternal);
});
